function Icon({ name }: { name: 'upload' | 'save' | 'spark' | 'download' | 'check' | 'warn' | 'settings' | 'close' | 'trash' }) {
  const paths = {
    upload: <><path d="M12 16V4m0 0L7 9m5-5 5 5" /><path d="M4 15v5h16v-5" /></>,
    save: <><path d="M5 3h12l2 2v16H5z" /><path d="M8 3v6h8V3M8 21v-7h8v7" /></>,
    spark: <><path d="m12 3 1.3 4.2L17.5 9l-4.2 1.8L12 15l-1.3-4.2L6.5 9l4.2-1.8z" /><path d="m19 15 .7 2.3L22 18l-2.3.7L19 21l-.7-2.3L16 18l2.3-.7z" /></>,
    download: <><path d="M12 4v12m0 0 5-5m-5 5-5-5" /><path d="M4 20h16" /></>,
    check: <path d="m5 12 4 4L19 6" />,
    warn: <><path d="M12 3 2.5 20h19z" /><path d="M12 9v5m0 3h.01" /></>,
    settings: <><circle cx="12" cy="12" r="3" /><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1a1.7 1.7 0 0 0 1.9.3A1.7 1.7 0 0 0 10 3V2.8h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z" /></>,
    close: <path d="m6 6 12 12M18 6 6 18" />,
    trash: <><path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14" /><path d="M10 11v6m4-6v6" /></>,
  }
  return <svg className="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>{paths[name]}</svg>
}

function Field({ label, value, onChange, placeholder = '' }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string }) {
  return <label className="field"><span>{label}</span><input value={value} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} /></label>
}

function pickerColor(value: string) { return /^#[0-9a-f]{6}$/i.test(value.trim()) ? value.trim() : '#000000' }

function MappingEditor({ label, hint, value, onChange, colors = false }: { label: string; hint: string; value: MappingEntry[]; onChange: (value: MappingEntry[]) => void; colors?: boolean }) {
  const rows = value.length ? value : [{ source: '', target: '' }]
  const update = (index: number, field: keyof MappingEntry, text: string) => onChange(rows.map((row, rowIndex) => rowIndex === index ? { ...row, [field]: text } : row))
  const input = (row: MappingEntry, index: number, field: keyof MappingEntry, placeholder: string) => colors ? <div className="color-input-group">
    <span className="color-sample" style={{ backgroundColor: pickerColor(row[field]) }} />
    <input className="color-picker" type="color" aria-label={`${label} ${field === 'source' ? 'origen' : 'destino'} selector ${index + 1}`} value={pickerColor(row[field])} onChange={(event) => update(index, field, event.target.value.toUpperCase())} />
    <input className="hex-input" aria-label={`${label} ${field === 'source' ? 'origen' : 'destino'} ${index + 1}`} placeholder={placeholder} value={row[field]} onChange={(event) => update(index, field, event.target.value)} />
  </div> : <input aria-label={`${label} ${field === 'source' ? 'origen' : 'destino'} ${index + 1}`} placeholder={placeholder} value={row[field]} onChange={(event) => update(index, field, event.target.value)} />
  return <fieldset className={`mapping-editor ${colors ? 'color-mappings' : ''}`}><legend>{label}</legend><p className="field-hint">{hint}</p>{rows.map((row, index) => <div className="mapping-row" key={index}>{input(row, index, 'source', colors ? '#000000' : 'Original')}<span>→</span>{input(row, index, 'target', colors ? '#000000' : 'Nuevo')}<button type="button" className="icon-button" aria-label={`Quitar mapeo de ${label}`} onClick={() => onChange(rows.filter((_, rowIndex) => rowIndex !== index))}>×</button></div>)}<button type="button" className="text-button" onClick={() => onChange([...rows, { source: '', target: '' }])}>+ Agregar mapeo</button></fieldset>
}

function sanitizeHtml(html: string): string {
  const document = new DOMParser().parseFromString(html, 'text/html')
  document.querySelectorAll('script, iframe, object, embed, form, meta[http-equiv]').forEach((node) => node.remove())
  document.querySelectorAll('*').forEach((element) => { for (const attribute of [...element.attributes]) { if (attribute.name.toLowerCase().startsWith('on')) element.removeAttribute(attribute.name); if (['href', 'src', 'action'].includes(attribute.name.toLowerCase()) && /^\s*javascript:/i.test(attribute.value)) element.removeAttribute(attribute.name) } })
  return `<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;padding:28px;color:#1c2635;line-height:1.5;overflow-wrap:anywhere}img{max-width:100%;height:auto}a{pointer-events:none}</style></head><body>${document.body.innerHTML}</body></html>`
}

function lineDiff(original: string, result: string) {
  const left = original.split(/\r?\n/), right = result.split(/\r?\n/)
  const table = Array.from({ length: left.length + 1 }, () => Array(right.length + 1).fill(0) as number[])
  for (let i = left.length - 1; i >= 0; i -= 1) for (let j = right.length - 1; j >= 0; j -= 1) table[i][j] = left[i] === right[j] ? table[i + 1][j + 1] + 1 : Math.max(table[i + 1][j], table[i][j + 1])
  const lines: { kind: 'same' | 'add' | 'remove'; text: string }[] = []; let i = 0, j = 0
  while (i < left.length && j < right.length) { if (left[i] === right[j]) { lines.push({ kind: 'same', text: left[i] }); i += 1; j += 1 } else if (table[i + 1][j] >= table[i][j + 1]) lines.push({ kind: 'remove', text: left[i++] }); else lines.push({ kind: 'add', text: right[j++] }) }
  while (i < left.length) lines.push({ kind: 'remove', text: left[i++] }); while (j < right.length) lines.push({ kind: 'add', text: right[j++] }); return lines
}

function guideWarnings(content: string): string[] {
  const warnings: string[] = []
  const variables = content.match(/(?<!\\)\$(?:!\{[^}\r\n]+\}|\{[^}\r\n]+\}|!?[A-Za-z_][\w.]*)/g)?.length ?? 0
  const directives = content.match(/(?<!#)#(?:if|elseif|foreach|set|macro|parse|include|evaluate|define|stop|else|end|break|continue)\b/gi)?.length ?? 0
  const urls = content.match(/(?:https?:\/\/|mailto:)[^\s<>"')\]]+/gi)?.length ?? 0
  const environments = [...new Set(content.match(/\b(?:sandbox|producci[oó]n|production|demo|tenant|identitynow|identitynow-demo)\b/gi) ?? [])]
  if (variables) warnings.push(`Se detectaron ${variables} variable(s) Velocity de ejemplo. Se neutralizarán antes de enviar la guía a la IA.`)
  if (directives) warnings.push(`Se detectaron ${directives} directiva(s) Velocity de ejemplo. Se neutralizarán antes de enviar la guía a la IA.`)
  if (urls) warnings.push(`Se detectaron ${urls} URL(s) o correo(s). Se retirarán de la guía enviada a la IA.`)
  if (environments.length) warnings.push(`La guía menciona ambientes o tenants que conviene revisar: ${environments.slice(0, 8).join(', ')}.`)
  return warnings
}

function Empty({ title, text }: { title: string; text: string }) { return <div className="empty"><div className="empty-mark">{`{ }`}</div><h3>{title}</h3><p>{text}</p></div> }

function templateIsPublished(template: TemplateSummary): boolean {
  return (template.publication_states ?? []).some((publication) =>
    publication.applies_to_current_result && publication.status.startsWith('published_')
  )
}

function ValidationPanel({ validation }: { validation: Validation | null }) {
  if (!validation) return <Empty title="Todavía no hay validación" text="Generá o guardá una adaptación para comparar variables y directivas." />
  const groups = [['Variables eliminadas', validation.missing_variables], ['Variables nuevas', validation.added_variables], ['Variables existentes repetidas', validation.repeated_variables ?? []], ['Directivas eliminadas', validation.missing_directives], ['Directivas agregadas', validation.added_directives], ['Orden de directivas', validation.directive_order_changed ? ['La secuencia de directivas cambió'] : []], ['Bloques de fecha alterados', validation.modified_protected_blocks ?? []], ['Referencias pendientes', validation.pending_old_client_references]] as const
  return <div className="validation-panel"><div className={`status-card ${validation.suspicious ? 'status-warn' : 'status-ok'}`}><Icon name={validation.suspicious ? 'warn' : 'check'} /><div><strong>{validation.suspicious ? 'Revisión requerida' : 'Sin diferencias sintácticas detectadas'}</strong><p>{validation.disclaimer}</p></div></div><div className="validation-grid">{groups.map(([title, entries]) => <section className="validation-group" key={title}><h4>{title} <span>{entries.length}</span></h4>{entries.length ? <ul>{entries.map((entry, index) => <li key={`${entry}-${index}`}><code>{entry}</code></li>)}</ul> : <p className="muted">Ninguna</p>}</section>)}</div></div>
}

function InstructionsRulesDialog({ config, provider, dirty, busy, guide, guideContent, guideFilename, guideDirty, onGuideContent, onGuideFilename, onSaveGuide, onDeleteGuide, onChange, onSave, onClose }: { config: BrandingConfig; provider: ProviderStatus; dirty: boolean; busy: string; guide: StyleGuide; guideContent: string; guideFilename: string; guideDirty: boolean; onGuideContent: (value: string) => void; onGuideFilename: (value: string) => void; onSaveGuide: () => void; onDeleteGuide: () => void; onChange: <K extends keyof BrandingConfig>(field: K, value: BrandingConfig[K]) => void; onSave: () => void; onClose: () => void }) {
  const warnings = guideDirty ? guideWarnings(guideContent) : guide.warnings
  return <div className="config-backdrop"><section className="config-dialog" role="dialog" aria-modal="true" aria-label="Instrucciones y reglas"><header className="config-header"><div><span className="eyebrow">Configuración compartida del proyecto</span><h2>Instrucciones y reglas</h2><p>Estas reglas se aplican a todas las notificaciones. Los campos vacíos conservan el contenido original.</p></div><div className="config-header-actions">{(dirty || guideDirty) && <span className="unsaved-badge">Cambios sin guardar</span>}<button className="icon-button close-button" aria-label="Cerrar instrucciones y reglas" onClick={onClose}><Icon name="close" /></button></div></header><div className="config-scroll"><div className="form-stack">
    <div className="mode-cards"><label className={config.mode === 'preserve' ? 'selected' : ''}><input type="radio" name="mode" checked={config.mode === 'preserve'} onChange={() => onChange('mode', 'preserve')} /><strong>Conservar diseño actual</strong><span>Cambia únicamente lo indicado.</span></label><label className={config.mode === 'guide' ? 'selected' : ''}><input type="radio" name="mode" checked={config.mode === 'guide'} onChange={() => onChange('mode', 'guide')} /><strong>Aplicar guía de estilo</strong><span>{provider.simulated ? 'La guía queda lista para usar con un proveedor con IA.' : 'La IA aplicará la guía Markdown guardada para este proyecto.'}</span></label></div>
    {config.mode === 'guide' && <section className="style-guide-editor"><div className="style-guide-heading"><div><strong>Guía Markdown del proyecto</strong><p>Define estructura, paleta, componentes, tono, firma y footer. Los ejemplos se sanean antes de enviarlos a la IA.</p></div><span className={`guide-status ${guideDirty ? 'dirty' : guide.configured ? 'saved' : ''}`}>{guideDirty ? 'Cambios sin guardar' : guide.configured ? 'Guardada' : 'Sin guía'}</span></div><div className="style-guide-tools"><label className="button secondary file-button"><Icon name="upload" />Cargar guía .md<input type="file" accept="text/markdown,.md,.markdown" onChange={(event) => { const input = event.currentTarget; const file = input.files?.[0]; if (file) void file.text().then((content) => { onGuideContent(content); onGuideFilename(file.name); input.value = '' }).catch(() => window.alert('No se pudo leer la guía Markdown seleccionada.')) }} /></label>{guideFilename && <span className="guide-filename" title={guideFilename}>{guideFilename}</span>}</div><label className="field"><span>Contenido Markdown</span><textarea className="guide-textarea" rows={16} value={guideContent} onChange={(event) => onGuideContent(event.target.value)} placeholder="# Guía de estilo&#10;&#10;Describí la estructura HTML, la paleta y las políticas editoriales del proyecto…" /></label>{warnings.length > 0 && <div className="guide-warnings"><strong>Advertencias detectadas</strong><ul>{warnings.map((warning) => <li key={warning}>{warning}</li>)}</ul></div>}<div className="style-guide-actions"><button className="button secondary" disabled={!guideDirty || !guideContent.trim() || Boolean(busy)} onClick={onSaveGuide}><Icon name="save" />{busy === 'guide' ? 'Guardando…' : guide.configured ? 'Reemplazar guía' : 'Guardar guía'}</button><button className="button danger" disabled={!guide.configured || Boolean(busy)} onClick={onDeleteGuide}>Limpiar guía</button></div></section>}
    <div className="language-settings"><Field label="Idioma de destino" value={config.target_language} onChange={(value) => onChange('target_language', value)} placeholder="Vacío: conservar idioma original" /><label className="checkbox-field"><input type="checkbox" checked={config.generate_missing_title} onChange={(event) => onChange('generate_missing_title', event.target.checked)} /><span><strong>Generar título visual si falta</strong><small>La IA lo deriva del nombre de la plantilla sin modificar name, key ni locale.</small></span></label></div>
    <div className="form-grid"><Field label="Cliente anterior" value={config.old_client_name} onChange={(value) => onChange('old_client_name', value)} /><Field label="Cliente nuevo" value={config.new_client_name} onChange={(value) => onChange('new_client_name', value)} /><Field label="Nombre visible del producto" value={config.product_display_name} onChange={(value) => onChange('product_display_name', value)} placeholder="Se conserva si está vacío" /><span /><Field label="URL del logo anterior" value={config.old_logo_url} onChange={(value) => onChange('old_logo_url', value)} /><Field label="URL del logo nuevo" value={config.new_logo_url} onChange={(value) => onChange('new_logo_url', value)} /><Field label="Saludo" value={config.greeting} onChange={(value) => onChange('greeting', value)} /><Field label="Tratamiento" value={config.treatment} onChange={(value) => onChange('treatment', value)} /></div>
    <label className="field"><span>Firma</span><textarea rows={3} value={config.signature} onChange={(event) => onChange('signature', event.target.value)} /></label>
    <label className="field"><span>Indicaciones de color</span><textarea rows={3} value={config.color_instructions} onChange={(event) => onChange('color_instructions', event.target.value)} placeholder={provider.simulated ? 'El modo simulado no interpreta paletas; usá los pares exactos de abajo.' : 'Ej.: usar azul petróleo como color principal y celeste para destacados.'} /><small>{provider.simulated ? 'Estas indicaciones quedarán guardadas para cuando uses un proveedor con IA.' : 'Estas indicaciones tienen prioridad sobre la guía de estilo.'}</small></label>
    <MappingEditor label="Reemplazos exactos de color (opcional)" colors hint={provider.simulated ? 'El modo simulado solo aplica pares completos.' : 'Sirven para forzar sustituciones concretas y tienen prioridad sobre la paleta inferida.'} value={config.color_mappings} onChange={(value) => onChange('color_mappings', value)} />
    <div className="mapping-columns"><MappingEditor label="Correos" hint="Mapeo exacto de origen a destino." value={config.email_mappings} onChange={(value) => onChange('email_mappings', value)} /><MappingEditor label="URLs" hint="Mapeo exacto; los parámetros dinámicos se conservan." value={config.url_mappings} onChange={(value) => onChange('url_mappings', value)} /></div>
    <label className="field"><span>Instrucciones adicionales</span><textarea rows={4} value={config.additional_instructions} onChange={(event) => onChange('additional_instructions', event.target.value)} placeholder={provider.simulated ? 'Se conservarán para cuando elijas un proveedor con IA.' : 'Excepciones particulares que deben prevalecer sobre la guía.'} /></label><div className={`mock-note ${provider.simulated ? '' : 'ai-enabled'}`}><Icon name={provider.simulated ? 'warn' : 'check'} /><p>{provider.simulated ? <><strong>Proveedor simulado activo:</strong> solo aplica reemplazos explícitos. Elegí un proveedor con IA para interpretar idioma, títulos, instrucciones, colores, saludo, firma y guía de estilo.</> : <><strong>Proveedor con IA activo: {provider.name}{provider.model ? ` · ${provider.model}` : ''}.</strong> Adaptará el texto a {config.target_language || 'su idioma original'} y aplicará la guía solamente cuando esté seleccionado ese modo. Los campos explícitos prevalecen sobre la guía; los correos y URLs requieren mapeos exactos.</>}</p></div>
  </div></div><footer className="config-footer"><span>{dirty || guideDirty ? 'Hay cambios del proyecto sin guardar.' : 'Instrucciones y reglas guardadas y listas para usar.'}</span><button className="button primary" disabled={!dirty || Boolean(busy)} onClick={onSave}><Icon name="save" />{busy === 'config' ? 'Guardando…' : 'Guardar instrucciones y reglas'}</button></footer></section></div>
}

function SettingsMenu({ provider, rulesDirty, aiDirty, onRules, onConnections, onAI }: { provider?: ProviderStatus; rulesDirty: boolean; aiDirty: boolean; onRules: () => void; onConnections: () => void; onAI: () => void }) {
  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const anyDirty = rulesDirty || aiDirty
  const menuItems = () => [...(rootRef.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]') ?? [])]
  const close = (restoreFocus = false) => {
    setOpen(false)
    if (restoreFocus) requestAnimationFrame(() => triggerRef.current?.focus())
  }
  const openAndFocus = (last = false) => {
    setOpen(true)
    requestAnimationFrame(() => {
      const items = menuItems()
      items[last ? items.length - 1 : 0]?.focus()
    })
  }
  const choose = (action: () => void) => {
    setOpen(false)
    action()
  }

  useEffect(() => {
    if (!open) return
    const handlePointer = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false)
    }
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault()
        close(true)
      }
    }
    document.addEventListener('mousedown', handlePointer)
    document.addEventListener('keydown', handleEscape)
    return () => {
      document.removeEventListener('mousedown', handlePointer)
      document.removeEventListener('keydown', handleEscape)
    }
  }, [open])

  const handleMenuKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return
    event.preventDefault()
    const items = menuItems()
    const current = items.indexOf(document.activeElement as HTMLButtonElement)
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : event.key === 'ArrowDown' ? (current + 1) % items.length : (current - 1 + items.length) % items.length
    items[next]?.focus()
  }

  return <div className="settings-menu" ref={rootRef}>
    <span className={`provider-pill ${provider?.connection.status ?? ''}`} title={provider ? `${provider.name}${provider.model ? ` · ${provider.model}` : ''}` : 'Conectando…'}><span className="pulse" /><span className="provider-name">{provider?.name ?? 'Conectando…'}</span>{provider?.model && <span className="provider-model"> · {provider.model}</span>}</span>
    <button ref={triggerRef} type="button" className={`settings-trigger ${anyDirty ? 'dirty' : ''}`} aria-label="Abrir menú de configuración" aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen((current) => !current)} onKeyDown={(event) => { if (event.key === 'ArrowDown' || event.key === 'ArrowUp') { event.preventDefault(); openAndFocus(event.key === 'ArrowUp') } }}><Icon name="settings" />{anyDirty && <span className="dirty-dot" aria-label="Hay cambios sin guardar" />}</button>
    {open && <div className="settings-dropdown" role="menu" aria-label="Configuración" onKeyDown={handleMenuKeyDown}>
      <button type="button" role="menuitem" onClick={() => choose(onRules)}><span><strong>Instrucciones y reglas</strong><small>Branding, guía y reglas del proyecto</small></span>{rulesDirty && <span className="menu-dirty" aria-label="Cambios sin guardar" />}</button>
      <button type="button" role="menuitem" onClick={() => choose(onConnections)}><span><strong>Conexiones ISC</strong><small>Tenants de origen y destino</small></span></button>
      <button type="button" role="menuitem" onClick={() => choose(onAI)}><span><strong>Configuración de IA</strong><small>{provider ? `${provider.name}${provider.model ? ` · ${provider.model}` : ''}` : 'Proveedor y modelo'}</small></span>{aiDirty && <span className="menu-dirty" aria-label="Cambios sin guardar" />}</button>
    </div>}
  </div>
}

const AI_PROVIDERS: { id: AIProviderId; label: string }[] = [
  { id: 'simulated', label: 'Simulado, para pruebas' },
  { id: 'gemini', label: 'Gemini' },
  { id: 'groq', label: 'Groq' },
  { id: 'anthropic', label: 'Anthropic / Claude' },
  { id: 'openai', label: 'OpenAI' },
  { id: 'openai_compatible', label: 'Servidor local compatible con OpenAI' },
]

function AISettings({ config, saved, provider, apiKey, busy, onChange, onApiKey, onSave, onTest, onClose }: { config: AIConfig; saved: AIConfig; provider: ProviderStatus; apiKey: string; busy: string; onChange: <K extends keyof AIConfig>(field: K, value: AIConfig[K]) => void; onApiKey: (value: string) => void; onSave: () => void; onTest: () => void; onClose: () => void }) {
  const dirty = JSON.stringify(config) !== JSON.stringify(saved) || Boolean(apiKey)
  const simulated = config.provider === 'simulated', local = config.provider === 'openai_compatible'
  return <div className="config-backdrop"><section className="config-dialog ai-dialog" role="dialog" aria-modal="true" aria-label="Configuración de IA"><header className="config-header"><div><span className="eyebrow">Proveedor de adaptación</span><h2>Configuración de IA</h2><p>El proveedor, modelo, URL y API key quedan guardados localmente en el backend para los próximos inicios.</p></div><div className="config-header-actions">{dirty && <span className="unsaved-badge">Cambios sin guardar</span>}<button className="icon-button close-button" aria-label="Cerrar configuración de IA" onClick={onClose}><Icon name="close" /></button></div></header><div className="config-scroll"><div className="form-stack">
    <label className="field"><span>Proveedor</span><select value={config.provider} onChange={(event) => { const next = event.target.value as AIProviderId; onChange('provider', next); if (next !== 'openai_compatible') onChange('base_url', '') }}>{AI_PROVIDERS.map((option) => <option value={option.id} key={option.id}>{option.label}</option>)}</select></label>
    {!simulated && <div className="form-grid"><Field label="Modelo" value={config.model} onChange={(value) => onChange('model', value)} placeholder="Identificador exacto del modelo" />{local ? <label className="field"><span>URL base OpenAI-compatible</span><input value={config.base_url} onChange={(event) => onChange('base_url', event.target.value)} placeholder="http://127.0.0.1:1234/v1" /><small>LM Studio: usá <code>/v1</code>, no <code>/api/v1</code>. Si escribís solo host y puerto, se agrega <code>/v1</code> al guardar.</small></label> : <span />}</div>}
    {!simulated && <label className="field"><span>API key {local ? '(opcional)' : ''}</span><input type="password" autoComplete="new-password" value={apiKey} onChange={(event) => onApiKey(event.target.value)} placeholder={provider.id === config.provider && provider.key_configured ? 'Clave guardada — dejá vacío para conservarla' : 'Ingresá una clave para guardarla en este equipo'} /><small>{provider.id === config.provider && provider.key_configured ? 'La clave está guardada en el backend. Podés reemplazarla sin visualizar la anterior.' : local ? 'LM Studio y Ollama locales normalmente no requieren clave; si ingresás una, también quedará guardada.' : 'Al guardar la configuración, la clave permanecerá disponible después de cerrar la app.'}</small></label>}
    <div className={`connection-card ${provider.connection.status}`}><Icon name={provider.connection.status === 'connected' ? 'check' : provider.connection.status === 'error' ? 'warn' : 'settings'} /><div><strong>{simulated ? 'Modo simulado' : `Estado: ${provider.connection.status === 'connected' ? 'Conectado' : provider.connection.status === 'error' ? 'Error de conexión' : 'Sin probar'}`}</strong><p>{provider.id === config.provider ? provider.connection.message : 'Guardá o probá esta selección para actualizar el estado.'}</p>{provider.id === config.provider && provider.model && <code>{provider.name} · {provider.model}</code>}</div></div>
    {!simulated && <p className="quota-warning"><Icon name="warn" />“Probar conexión” realiza una solicitud mínima al modelo y puede consumir cuota. Para LM Studio, iniciá el servidor, cargá el modelo y usá su endpoint OpenAI-compatible <code>/v1</code>. Los modelos locales pueden tardar varios minutos al adaptar una plantilla extensa.</p>}
  </div></div><footer className="config-footer ai-footer"><button className="button secondary" title={dirty ? 'Guardá la configuración antes de probar la conexión.' : ''} disabled={dirty || Boolean(busy) || (!simulated && (!config.model.trim() || (local && !config.base_url.trim())))} onClick={onTest}>{busy === 'ai-test' ? 'Probando…' : 'Probar conexión'}</button><button className="button primary" disabled={!dirty || Boolean(busy)} onClick={onSave}><Icon name="save" />{busy === 'ai-save' ? 'Guardando…' : 'Guardar configuración de IA'}</button></footer></section></div>
}

const EMPTY_ISC_CONNECTION: ISCConnectionInput = { name: '', environment: 'sandbox', api_base_url: '', client_id: '', client_secret: '' }
function ISCConnectionsDialog({ connections, onConnections, onClose }: { connections: ISCConnection[]; onConnections: (connections: ISCConnection[]) => void; onClose: () => void }) {
  const [selectedId, setSelectedId] = useState(connections[0]?.id ?? '')
  const selected = connections.find((connection) => connection.id === selectedId)
  const [draft, setDraft] = useState<ISCConnectionInput>(selected ? { name: selected.name, environment: selected.environment, api_base_url: selected.api_base_url, client_id: '', client_secret: '' } : EMPTY_ISC_CONNECTION)
  const [busy, setBusy] = useState(''), [notice, setNotice] = useState<{ kind: 'ok' | 'error'; text: string } | null>(null)
  const dirty = selected ? draft.name !== selected.name || draft.environment !== selected.environment || draft.api_base_url !== selected.api_base_url || Boolean(draft.client_id || draft.client_secret) : Object.values(draft).some(Boolean) && Boolean(draft.name || draft.api_base_url || draft.client_id || draft.client_secret)
  const choose = (connection?: ISCConnection) => { setSelectedId(connection?.id ?? ''); setDraft(connection ? { name: connection.name, environment: connection.environment, api_base_url: connection.api_base_url, client_id: '', client_secret: '' } : { ...EMPTY_ISC_CONNECTION }); setNotice(null) }
  const setField = <K extends keyof ISCConnectionInput>(field: K, value: ISCConnectionInput[K]) => setDraft((current) => ({ ...current, [field]: value }))
  const save = async () => { setBusy('save'); setNotice(null); try { const saved = selected ? await api.updateISCConnection(PROJECT_ID, selected.id, draft) : await api.createISCConnection(PROJECT_ID, draft); const next = selected ? connections.map((connection) => connection.id === saved.id ? saved : connection) : [...connections, saved]; onConnections(next); choose(saved); setNotice({ kind: 'ok', text: 'Conexión guardada. Las credenciales quedaron únicamente en el backend.' }) } catch (error) { setNotice({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const test = async () => { if (!selected) return; setBusy('test'); setNotice(null); try { const result = await api.testISCConnection(PROJECT_ID, selected.id); onConnections(connections.map((connection) => connection.id === selected.id ? result.connection : connection)); choose(result.connection); setNotice({ kind: result.connection.status === 'connected' ? 'ok' : 'error', text: result.message }) } catch (error) { const refreshed = await api.iscConnections(PROJECT_ID); onConnections(refreshed.connections); const updated = refreshed.connections.find((connection) => connection.id === selected.id); if (updated) choose(updated); setNotice({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const remove = async () => { if (!selected || !window.confirm(`¿Eliminar la conexión “${selected.name}”?\n\nSe quitarán la conexión y sus credenciales locales. Las notificaciones ya importadas no se eliminarán.`)) return; setBusy('delete'); setNotice(null); try { await api.deleteISCConnection(PROJECT_ID, selected.id); const next = connections.filter((connection) => connection.id !== selected.id); onConnections(next); choose(next[0]); setNotice({ kind: 'ok', text: `Conexión “${selected.name}” y sus credenciales locales eliminadas.` }) } catch (error) { setNotice({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  return <div className="config-backdrop"><section className="config-dialog isc-connections-dialog" role="dialog" aria-modal="true" aria-label="Conexiones ISC"><header className="config-header"><div><span className="eyebrow">Consulta y publicación controlada</span><h2>Conexiones ISC</h2><p>Configurá varios tenants. Las credenciales PAT se guardan en el backend y nunca vuelven al navegador.</p></div><button className="icon-button close-button" aria-label="Cerrar conexiones ISC" onClick={onClose}><Icon name="close" /></button></header><div className="isc-connections-layout"><aside className="isc-connection-list"><button className="button primary" onClick={() => choose()}>+ Nueva conexión</button>{connections.map((connection) => <button key={connection.id} className={`isc-connection-item ${selectedId === connection.id ? 'selected' : ''}`} onClick={() => choose(connection)}><strong>{connection.name}</strong><span>{ENVIRONMENT_LABELS[connection.environment]} · {connection.status === 'connected' ? 'Conectada' : connection.status === 'limited' ? 'Permisos limitados' : connection.status === 'error' ? 'Error' : 'Sin probar'}</span></button>)}</aside><div className="isc-connection-form"><div className="form-grid"><Field label="Nombre de la conexión" value={draft.name} onChange={(value) => setField('name', value)} placeholder="Ej.: Cliente · Producción" /><label className="field"><span>Entorno</span><select value={draft.environment} onChange={(event) => setField('environment', event.target.value as ISCEnvironment)}><option value="sandbox">Sandbox</option><option value="production">Producción</option><option value="demo">Demo</option></select></label></div><Field label="URL base exacta de la API" value={draft.api_base_url} onChange={(value) => setField('api_base_url', value)} placeholder="https://tenant.api.identitynow.com" /><p className="field-hint">Solo HTTPS y hosts tenant.api.identitynow.com o tenant.api.identitynow-demo.com, sin rutas, parámetros ni puertos.</p><div className="form-grid"><label className="field"><span>PAT Client ID</span><input type="password" autoComplete="new-password" value={draft.client_id} onChange={(event) => setField('client_id', event.target.value)} placeholder={selected?.client_id_configured ? 'Configurado — vacío conserva el actual' : 'Client ID'} /></label><label className="field"><span>PAT Client Secret</span><input type="password" autoComplete="new-password" value={draft.client_secret} onChange={(event) => setField('client_secret', event.target.value)} placeholder={selected?.secret_configured ? 'Configurado — vacío conserva el actual' : 'Client Secret'} /></label></div>{selected && <div className={`connection-card ${selected.status === 'connected' ? 'connected' : selected.status === 'error' ? 'error' : ''}`}><Icon name={selected.status === 'connected' ? 'check' : selected.status === 'error' ? 'warn' : 'settings'} /><div><strong>{selected.status === 'connected' ? 'Conexión disponible' : selected.status === 'limited' ? 'Autenticada con permisos limitados' : selected.status === 'error' ? 'Error de conexión' : 'Conexión sin probar'}</strong><p>{selected.status_message}</p><code>Client ID: {selected.client_id_configured ? 'configurado' : 'faltante'} · Secret: {selected.secret_configured ? 'configurado' : 'faltante'}</code></div></div>}{notice && <div className={`dialog-notice ${notice.kind}`}>{notice.text}</div>}<p className="field-hint">Para publicar también se requiere <code>idn:notification-templates:create</code>. La prueba verifica autenticación y permisos de lectura sin escribir en ISC.</p><div className="isc-form-actions">{selected && <button className="button danger" disabled={Boolean(busy)} onClick={() => void remove()}>{busy === 'delete' ? 'Eliminando…' : 'Eliminar conexión'}</button>}<span className="action-spacer" /><button className="button secondary" disabled={!selected || dirty || Boolean(busy)} title={dirty ? 'Guardá los cambios antes de probar.' : 'Autentica y verifica los permisos de lectura sin realizar escrituras.'} onClick={() => void test()}>{busy === 'test' ? 'Probando…' : 'Probar conexión'}</button><button className="button primary" disabled={!dirty || Boolean(busy)} onClick={() => void save()}><Icon name="save" />{busy === 'save' ? 'Guardando…' : 'Guardar conexión'}</button></div></div></div></section></div>
}

function ISCImportDialog({ connections, templates, onManageConnections, onImported, onClose }: { connections: ISCConnection[]; templates: TemplateSummary[]; onManageConnections: () => void; onImported: (result: ISCImportResult) => Promise<void>; onClose: () => void }) {
  const [connectionId, setConnectionId] = useState(connections[0]?.id ?? ''), [templateType, setTemplateType] = useState<ISCTemplateType>('custom')
  const [candidates, setCandidates] = useState<ISCTemplateCandidate[]>([]), [selectedIds, setSelectedIds] = useState<Set<string>>(new Set()), [filter, setFilter] = useState(''), [strategy, setStrategy] = useState<'skip' | 'replace' | 'copy'>('skip')
  const [busy, setBusy] = useState(''), [notice, setNotice] = useState<{ kind: 'ok' | 'error'; text: string } | null>(null)
  const visible = useMemo(() => { const query = filter.trim().toLocaleLowerCase(); return candidates.filter((candidate) => [candidate.name, candidate.key, candidate.locale].some((value) => value.toLocaleLowerCase().includes(query))) }, [candidates, filter])
  const identity = (value: { key: string; medium: string; locale: string }) => `${value.key.toLocaleLowerCase()}\u0000${value.medium.toLocaleLowerCase()}\u0000${value.locale.toLocaleLowerCase()}`
  const existing = useMemo(() => {
    const byIdentity = new Map<string, TemplateSummary>()
    templates.forEach((template) => {
      const key = identity(template), current = byIdentity.get(key)
      if (!current || (current.local_copy && !template.local_copy)) byIdentity.set(key, template)
    })
    return byIdentity
  }, [templates])
  const chosen = candidates.filter((candidate) => selectedIds.has(candidate.selection_id)), duplicates = chosen.map((candidate) => existing.get(identity(candidate))).filter(Boolean) as TemplateSummary[]
  const adaptedDuplicates = duplicates.filter((template) => template.has_result).length
  const query = async () => { if (!connectionId) return; setBusy('query'); setNotice(null); try { const result = await api.listISCTemplates(PROJECT_ID, connectionId, templateType); setCandidates(result.templates); setSelectedIds(new Set()); setNotice({ kind: 'ok', text: `${result.templates.length} plantilla(s) disponibles. Elegí cuáles importar.` }) } catch (error) { setCandidates([]); setSelectedIds(new Set()); setNotice({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const importSelected = async () => { if (!chosen.length) return; setBusy('import'); setNotice(null); try { const result = await api.importISCTemplates(PROJECT_ID, connectionId, templateType, chosen.map((candidate) => candidate.template), strategy); await onImported(result); setNotice({ kind: 'ok', text: `Importadas: ${result.imported}. Copias locales: ${result.copied}. Omitidas: ${result.skipped}. Reemplazadas: ${result.replaced}.` }); setSelectedIds(new Set()) } catch (error) { setNotice({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const toggle = (candidate: ISCTemplateCandidate) => setSelectedIds((current) => { const next = new Set(current); next.has(candidate.selection_id) ? next.delete(candidate.selection_id) : next.add(candidate.selection_id); return next })
  return <div className="config-backdrop"><section className="config-dialog isc-import-dialog" role="dialog" aria-modal="true" aria-label="Cargar desde ISC"><header className="config-header"><div><span className="eyebrow">Consulta remota de solo lectura</span><h2>Cargar plantillas desde ISC</h2><p>La consulta no publica, modifica ni elimina contenido en SailPoint.</p></div><button className="icon-button close-button" aria-label="Cerrar importación ISC" onClick={onClose}><Icon name="close" /></button></header>{connections.length === 0 ? <Empty title="Primero creá una conexión ISC" text="Necesitás una URL de API válida y credenciales PAT con permisos de lectura." /> : <><div className="isc-query-bar"><label className="field"><span>Conexión</span><select value={connectionId} onChange={(event) => { setConnectionId(event.target.value); setCandidates([]); setSelectedIds(new Set()) }}>{connections.map((connection) => <option key={connection.id} value={connection.id}>{connection.name} · {ENVIRONMENT_LABELS[connection.environment]}</option>)}</select></label><label className="field"><span>Tipo de plantilla</span><select value={templateType} onChange={(event) => { setTemplateType(event.target.value as ISCTemplateType); setCandidates([]); setSelectedIds(new Set()) }}><option value="custom">Personalizadas</option><option value="standard">Estándar</option></select></label><button className="button secondary" disabled={!connectionId || Boolean(busy)} onClick={() => void query()}>{busy === 'query' ? 'Consultando…' : 'Consultar ISC'}</button><button className="text-button" onClick={onManageConnections}>Administrar conexiones</button></div><div className="isc-import-tools"><div className="search"><span>⌕</span><input aria-label="Filtrar plantillas ISC" placeholder="Nombre, key o locale" value={filter} onChange={(event) => setFilter(event.target.value)} /></div><button className="text-button" onClick={() => setSelectedIds((current) => new Set([...current, ...visible.map((candidate) => candidate.selection_id)]))}>Seleccionar visibles</button><button className="text-button" onClick={() => setSelectedIds(new Set())}>Limpiar selección</button><strong>{selectedIds.size} seleccionada(s)</strong></div><div className="isc-candidate-list">{visible.map((candidate) => { const duplicate = existing.get(identity(candidate)); return <label className="isc-candidate" key={candidate.selection_id}><input type="checkbox" checked={selectedIds.has(candidate.selection_id)} onChange={() => toggle(candidate)} /><span><strong>{candidate.name}</strong><code>{candidate.key || 'sin key'}</code></span><span className="chips"><span>{candidate.locale || '—'}</span>{duplicate && <span className={duplicate.has_result ? 'unsafe' : 'outdated'}>{duplicate.has_result ? 'Duplicada con adaptación' : 'Duplicada'}</span>}</span></label> })}{!visible.length && <Empty title={candidates.length ? 'Sin coincidencias' : 'Consultá una conexión'} text={candidates.length ? 'Probá con otro filtro.' : 'Se consultará la colección completa y se mostrarán únicamente plantillas EMAIL.'} />}</div></>}{notice && <div className={`dialog-notice import-notice ${notice.kind}`}>{notice.text}</div>}<footer className="config-footer isc-import-footer">{connections.length === 0 ? <button className="button primary" onClick={onManageConnections}>Crear conexión ISC</button> : <><div className="duplicate-options">{duplicates.length > 0 && <><strong>{duplicates.length} duplicada(s) por key + medium + locale</strong><label><input type="radio" checked={strategy === 'skip'} onChange={() => setStrategy('skip')} /> Omitir</label><label><input type="radio" checked={strategy === 'replace'} onChange={() => setStrategy('replace')} /> Reemplazar original</label><label><input type="radio" checked={strategy === 'copy'} onChange={() => setStrategy('copy')} /> Importar como copia</label>{strategy === 'replace' && adaptedDuplicates > 0 && <span className="danger-text">Se perderán {adaptedDuplicates} adaptación(es) existentes.</span>}{strategy === 'copy' && <span className="field-hint">La copia será independiente localmente, pero apuntará al mismo destino al publicar.</span>}</>}</div><button className="button primary" disabled={!chosen.length || Boolean(busy)} onClick={() => void importSelected()}><Icon name="upload" />{busy === 'import' ? 'Importando…' : `Importar ${chosen.length || ''}`}</button></>}</footer></section></div>
}

function App() {
  const [project, setProject] = useState<Project | null>(null), [config, setConfig] = useState<BrandingConfig | null>(null), [savedConfig, setSavedConfig] = useState<BrandingConfig | null>(null)
  const [styleGuide, setStyleGuide] = useState<StyleGuide>({ configured: false, content: '', filename: '', updated_at: null, hash: '', warnings: [] }), [guideContent, setGuideContent] = useState(''), [guideFilename, setGuideFilename] = useState('')
  const [configOpen, setConfigOpen] = useState(false), [aiOpen, setAiOpen] = useState(false), [iscConnectionsOpen, setISCConnectionsOpen] = useState(false), [iscImportOpen, setISCImportOpen] = useState(false), [publicationIntent, setPublicationIntent] = useState<'download' | 'publish' | null>(null), [selectedId, setSelectedId] = useState(''), [detail, setDetail] = useState<TemplateDetail | null>(null), [filter, setFilter] = useState('')
  const [iscConnections, setISCConnections] = useState<ISCConnection[]>([])
  const [aiConfig, setAiConfig] = useState<AIConfig>({ provider: 'simulated', model: '', base_url: '' }), [savedAIConfig, setSavedAIConfig] = useState<AIConfig>({ provider: 'simulated', model: '', base_url: '' }), [apiKey, setApiKey] = useState('')
  const [workTab, setWorkTab] = useState<WorkTab>('preview'), [previewVersion, setPreviewVersion] = useState<PreviewVersion>('original'), [subject, setSubject] = useState(''), [body, setBody] = useState('')
  const [editorMode, setEditorMode] = useState<EditorMode>('visual'), [visualIntegrity, setVisualIntegrity] = useState(true)
  const [busy, setBusy] = useState(''), [message, setMessage] = useState<{ kind: 'ok' | 'error'; text: string } | null>(null)
  const selectedIdRef = useRef(selectedId)
  const selectTemplate = (internalId: string) => { selectedIdRef.current = internalId; setDetail(null); setSubject(''); setBody(''); setSelectedId(internalId) }
  const configDirty = useMemo(() => Boolean(config && savedConfig && JSON.stringify(config) !== JSON.stringify(savedConfig)), [config, savedConfig])
  const guideDirty = guideContent !== styleGuide.content || guideFilename !== styleGuide.filename

  const loadProject = async () => { try { const [loaded, guide] = await Promise.all([api.project(PROJECT_ID), api.styleGuide(PROJECT_ID)]); setProject(loaded); setConfig(loaded.config); setSavedConfig(structuredClone(loaded.config)); setStyleGuide(guide); setGuideContent(guide.content); setGuideFilename(guide.filename); setAiConfig(loaded.ai_config); setSavedAIConfig(structuredClone(loaded.ai_config)); if (loaded.templates.length && !selectedIdRef.current) selectTemplate(loaded.templates[0].internal_id) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } }
  const refreshDetailIfSelected = async (targetId: string) => { const loaded = await api.detail(PROJECT_ID, targetId); if (selectedIdRef.current === targetId) { setDetail(loaded); setSubject(loaded.result_subject ?? ''); setBody(loaded.result_body ?? '') } return loaded }
  useEffect(() => { void loadProject() }, [])
  useEffect(() => { void api.iscConnections(PROJECT_ID).then((response) => setISCConnections(response.connections)).catch((error) => setMessage({ kind: 'error', text: (error as Error).message })) }, [])
  useEffect(() => { selectedIdRef.current = selectedId }, [selectedId])
  useEffect(() => { if (!selectedId) { setDetail(null); setSubject(''); setBody(''); return } const controller = new AbortController(); const requestedId = selectedId; setDetail(null); setSubject(''); setBody(''); void api.detail(PROJECT_ID, requestedId, controller.signal).then((loaded) => { if (selectedIdRef.current !== requestedId) return; setDetail(loaded); setSubject(loaded.result_subject ?? ''); setBody(loaded.result_body ?? ''); setPreviewVersion(loaded.result ? 'adapted' : 'original'); setEditorMode('visual'); setVisualIntegrity(true); setWorkTab('preview') }).catch((error) => { if (!(error instanceof ApiRequestCancelled) && selectedIdRef.current === requestedId) setMessage({ kind: 'error', text: (error as Error).message }) }); return () => controller.abort() }, [selectedId])

  const visibleTemplates = useMemo(() => { const query = filter.trim().toLocaleLowerCase(); return (project?.templates ?? []).filter((template) => [template.name, template.key, template.medium, template.locale].some((value) => value.toLocaleLowerCase().includes(query))) }, [project?.templates, filter])
  const visibleBody = previewVersion === 'adapted' && detail?.result ? body : detail?.original_body ?? '', visibleSubject = previewVersion === 'adapted' && detail?.result ? subject : detail?.original_subject ?? ''
  const previewHtml = useMemo(() => sanitizeHtml(visibleBody), [visibleBody]), previewSubject = visibleSubject
  const diff = useMemo(() => lineDiff(detail?.original_body ?? '', body), [detail?.original_body, body])
  const visualIssues = useMemo(() => body ? visualSafetyIssues(body) : [], [body])
  useEffect(() => { if (visualIssues.length && editorMode === 'visual') setEditorMode('html') }, [visualIssues, editorMode])

  const importFile = async (file?: File) => { if (!file) return; setBusy('import'); setMessage(null); try { const data = JSON.parse(await file.text()) as unknown, response = await api.import(PROJECT_ID, file.name, data), refreshed = await api.project(PROJECT_ID), firstId = response.templates[0]?.internal_id ?? ''; setProject(refreshed); selectTemplate(firstId); if (!firstId) setDetail(null); setWorkTab('preview'); setPreviewVersion('original'); setMessage({ kind: 'ok', text: `${response.templates.length} notificación(es) cargada(s). Los originales quedaron guardados por separado.` }) } catch (error) { setMessage({ kind: 'error', text: error instanceof SyntaxError ? 'El archivo no contiene JSON válido.' : (error as Error).message }) } finally { setBusy('') } }
  const saveConfig = async () => { if (!config) return; const targetId = selectedIdRef.current; setBusy('config'); setMessage(null); try { await api.saveConfig(PROJECT_ID, config); setSavedConfig(structuredClone(config)); setProject(await api.project(PROJECT_ID)); if (targetId) await refreshDetailIfSelected(targetId); setMessage({ kind: 'ok', text: 'Instrucciones y reglas guardadas. Las adaptaciones anteriores quedaron señaladas para revisión.' }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const saveGuide = async () => { const targetId = selectedIdRef.current; setBusy('guide'); setMessage(null); try { const saved = await api.saveStyleGuide(PROJECT_ID, guideContent, guideFilename || 'guia-estilo.md'); setStyleGuide(saved); setGuideContent(saved.content); setGuideFilename(saved.filename); setProject(await api.project(PROJECT_ID)); if (targetId) await refreshDetailIfSelected(targetId); setMessage({ kind: 'ok', text: 'Guía de estilo guardada. Las adaptaciones anteriores quedaron desactualizadas y las preparaciones de publicación se invalidaron.' }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const deleteGuide = async () => { if (!window.confirm('¿Limpiar la guía de estilo de este proyecto?\n\nLas adaptaciones existentes no se borrarán, pero quedarán desactualizadas.')) return; const targetId = selectedIdRef.current; setBusy('guide'); setMessage(null); try { const cleared = await api.deleteStyleGuide(PROJECT_ID); setStyleGuide(cleared); setGuideContent(''); setGuideFilename(''); setProject(await api.project(PROJECT_ID)); if (targetId) await refreshDetailIfSelected(targetId); setMessage({ kind: 'ok', text: 'Guía de estilo eliminada. Para generar, usá “Conservar diseño actual” o guardá una guía nueva.' }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const saveAIConfig = async () => { const targetId = selectedIdRef.current; setBusy('ai-save'); setMessage(null); try { await api.saveAIConfig(PROJECT_ID, aiConfig, apiKey); setApiKey(''); const refreshed = await api.project(PROJECT_ID); setProject(refreshed); setAiConfig(refreshed.ai_config); setSavedAIConfig(structuredClone(refreshed.ai_config)); if (targetId) await refreshDetailIfSelected(targetId); setMessage({ kind: 'ok', text: 'Configuración de IA guardada. Las adaptaciones anteriores quedaron señaladas para revisión.' }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const testAIConnection = async () => { setBusy('ai-test'); setMessage(null); try { const response = await api.testAIConnection(PROJECT_ID, aiConfig, apiKey); setProject((current) => current ? { ...current, provider: response.provider } : current); setApiKey(''); setMessage({ kind: 'ok', text: response.message }) } catch (error) { try { setProject(await api.project(PROJECT_ID)) } catch { /* El error original es el más útil para el usuario. */ } setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const adapt = async () => { const targetId = selectedIdRef.current; if (!targetId || configDirty) return; setBusy('adapt'); setMessage(null); try { const loaded = await api.adapt(PROJECT_ID, targetId); if (selectedIdRef.current === targetId) { setDetail(loaded); setSubject(loaded.result_subject ?? ''); setBody(loaded.result_body ?? ''); setPreviewVersion('adapted'); setWorkTab('preview') } setProject(await api.project(PROJECT_ID)); setMessage({ kind: 'ok', text: `${project?.provider.simulated ? 'Adaptación simulada' : 'Adaptación con IA'} generada. Revisá diferencias y validación antes de descargar.` }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const saveEdit = async () => { const targetId = selectedIdRef.current; if (!targetId || (editorMode === 'visual' && (!visualIntegrity || visualIssues.length))) return; setBusy('edit'); setMessage(null); try { const loaded = await api.edit(PROJECT_ID, targetId, subject, body, editorMode); if (selectedIdRef.current === targetId) setDetail(loaded); setProject(await api.project(PROJECT_ID)); setMessage({ kind: 'ok', text: loaded.validation?.suspicious ? 'Edición guardada. La validación detectó cambios que requieren revisión.' : 'Resultado editado y validado.' }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const toggleDateTranslation = async () => { const targetId = selectedIdRef.current; if (!targetId || !detail?.result) return; const enable = !detail.date_translation.applied; setBusy('date-translation'); setMessage(null); try { const loaded = await api.updateDateTranslation(PROJECT_ID, targetId, enable); if (selectedIdRef.current === targetId) { setDetail(loaded); setSubject(loaded.result_subject ?? ''); setBody(loaded.result_body ?? ''); setPreviewVersion('adapted') } setProject(await api.project(PROJECT_ID)); const variables = (enable ? loaded.date_translation.variables : detail.date_translation.variables).map((variable) => `$${variable}`).join(', '); setMessage({ kind: 'ok', text: enable ? `Fechas traducidas de forma determinista${variables ? `: ${variables}` : ''}. Revisá la vista previa antes de publicar.` : 'Se quitó la traducción determinista de fechas y se restauraron las referencias originales.' }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const finishISCImport = async (result: ISCImportResult) => { const refreshed = await api.project(PROJECT_ID); setProject(refreshed); const nextId = result.internal_ids[0]; if (nextId) selectTemplate(nextId); setMessage({ kind: 'ok', text: `Importación desde ISC completada: ${result.imported} importada(s), ${result.copied} como copia(s), ${result.skipped} omitida(s), ${result.replaced} reemplazada(s).` }) }
  const deleteNotification = async (template: TemplateSummary) => { if (!window.confirm(`¿Eliminar “${template.name}” del proyecto?\n\nSe borrarán el original y su adaptación local. Esta acción no modifica SailPoint.`)) return; setBusy('delete-template'); setMessage(null); try { const response = await api.deleteTemplate(PROJECT_ID, template.internal_id); setProject(await api.project(PROJECT_ID)); if (selectedIdRef.current === template.internal_id) { const nextId = response.templates[0]?.internal_id ?? ''; selectTemplate(nextId); if (!nextId) setDetail(null) } setMessage({ kind: 'ok', text: `Notificación “${response.name}” eliminada del proyecto local.` }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const clearNotifications = async () => { const count = project?.templates.length ?? 0; if (!count || !window.confirm(`¿Eliminar las ${count} notificaciones del panel?\n\nSe borrarán todos los originales y adaptaciones locales. Las conexiones y configuraciones se conservarán. Esta acción no modifica SailPoint.`)) return; setBusy('clear-templates'); setMessage(null); try { const response = await api.clearTemplates(PROJECT_ID); const refreshed = await api.project(PROJECT_ID); setProject(refreshed); selectTemplate(''); setDetail(null); setSubject(''); setBody(''); setPreviewVersion('original'); setWorkTab('preview'); setMessage({ kind: 'ok', text: `Panel limpio: se eliminaron ${response.deleted} notificación(es) locales.` }) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } finally { setBusy('') } }
  const setConfigField = <K extends keyof BrandingConfig>(field: K, value: BrandingConfig[K]) => setConfig((current) => current ? { ...current, [field]: value } : current)
  const setAIField = <K extends keyof AIConfig>(field: K, value: AIConfig[K]) => setAiConfig((current) => ({ ...current, [field]: value }))
  const aiDirty = JSON.stringify(aiConfig) !== JSON.stringify(savedAIConfig) || Boolean(apiKey)
  const closeAISettings = () => { setAiOpen(false) }
  const refreshAfterPublication = async () => { const targetId = selectedIdRef.current; await loadProject(); if (targetId) { try { await refreshDetailIfSelected(targetId) } catch (error) { setMessage({ kind: 'error', text: (error as Error).message }) } } }
  const unsafeVelocity = Boolean(detail?.validation && (detail.validation.missing_variables.length || detail.validation.added_variables.length || detail.validation.missing_directives.length || detail.validation.added_directives.length || detail.validation.directive_order_changed || detail.validation.modified_protected_blocks?.length))
  const unsafeVelocityCount = detail?.validation ? detail.validation.missing_variables.length + detail.validation.added_variables.length + detail.validation.missing_directives.length + detail.validation.added_directives.length + (detail.validation.directive_order_changed ? 1 : 0) + (detail.validation.modified_protected_blocks?.length ?? 0) : 0
  const generateDisabledReason = !selectedId ? 'Seleccioná una notificación.' : configDirty ? 'Guardá las instrucciones y reglas antes de generar.' : guideDirty ? 'Guardá o descartá los cambios de la guía antes de generar.' : config?.mode === 'guide' && !styleGuide.configured ? 'El modo guía requiere una guía Markdown guardada.' : aiDirty ? 'Guardá la configuración de IA antes de generar.' : !project?.provider.simulated && !project?.provider.model ? 'Configurá un modelo de IA.' : busy ? 'Hay una operación en curso.' : '', generationLabel = project?.provider.simulated ? 'Generar adaptación simulada' : `Generar con ${project?.provider.name ?? 'IA'}`
  const dateTranslationDisabledReason = !detail?.result ? 'Primero generá una adaptación.' : unsafeVelocity ? 'Corregí los cambios de variables o directivas Velocity.' : detail.config_outdated || configDirty || guideDirty ? 'La adaptación debe corresponder a la configuración y guía vigentes.' : !detail.date_translation.language_supported ? 'Esta acción está disponible cuando el idioma de destino es español.' : detail.date_translation.applied && !detail.date_translation.removable ? 'Esta adaptación usa un bloque anterior que no puede quitarse automáticamente.' : !detail.date_translation.applied && !detail.date_translation.available_variables.length ? 'No se encontraron fechas visibles compatibles: expires, dateRequested, startDate, removeDate, detail.startDate o detail.removeDate.' : busy ? 'Hay una operación en curso.' : ''
  const dateTranslationLabel = detail?.date_translation.applied ? 'Quitar traducción de fechas' : 'Traducir fechas'
  const publicationDisabledReason = !detail?.result ? 'Primero generá una adaptación.' : unsafeVelocity ? 'Corregí los cambios de variables o directivas Velocity.' : detail.config_outdated || configDirty || guideDirty ? 'La adaptación debe corresponder a la configuración y guía vigentes.' : !iscConnections.length ? 'Primero configurá una conexión ISC.' : ''

  return <div className="app-shell"><header className="topbar"><div className="header-left"><div className="brand"><h1><span className="brand-prefix">ISC</span><span aria-hidden> · </span>Email Generator</h1></div></div><div className="top-actions"><SettingsMenu provider={project?.provider} rulesDirty={configDirty || guideDirty} aiDirty={aiDirty} onRules={() => setConfigOpen(true)} onConnections={() => setISCConnectionsOpen(true)} onAI={() => setAiOpen(true)} /></div></header>
    {message && <div className={`toast ${message.kind}`} role="status"><span>{message.kind === 'ok' ? '✓' : '!'}</span>{message.text}<button onClick={() => setMessage(null)}>×</button></div>}
    <main className="workspace"><aside className="panel sidebar"><div className="panel-heading"><div><span className="eyebrow">Proyecto local</span><h2>Notificaciones</h2></div><span className="count">{project?.templates.length ?? 0}</span></div><div className="sidebar-load-actions"><label className="button primary sidebar-upload"><Icon name="upload" />{busy === 'import' ? 'Cargando…' : 'Cargar JSON'}<input type="file" accept="application/json,.json" disabled={!!busy} onChange={(event) => { const input = event.currentTarget; void importFile(input.files?.[0]).finally(() => { input.value = '' }) }} /></label><button className="button secondary" disabled={Boolean(busy)} onClick={() => setISCImportOpen(true)}><Icon name="upload" />Cargar desde ISC</button></div>{project?.filename && <p className="filename" title={project.filename}>Archivo: <strong>{project.filename}</strong></p>}<div className="search"><span>⌕</span><input aria-label="Filtrar notificaciones" placeholder="Nombre, key, medium o locale" value={filter} onChange={(event) => setFilter(event.target.value)} /></div><div className="template-list">{visibleTemplates.map((template: TemplateSummary) => <div className={`template-item ${selectedId === template.internal_id ? 'selected' : ''}`} key={template.internal_id}><button className="template-select" onClick={() => selectTemplate(template.internal_id)}><span className="template-title">{template.name}</span><code>{template.key || 'sin key'}</code><span className="chips"><span>{template.locale || '—'}</span>{template.provenance && <span>ISC</span>}{template.local_copy && <span className="local-copy">Copia local</span>}{template.has_result && <span className={template.unsafe_result ? 'unsafe' : template.config_outdated ? 'outdated' : 'adapted'}>{template.unsafe_result ? 'Revisión requerida' : template.config_outdated ? 'Desactualizada' : 'Adaptada'}</span>}{templateIsPublished(template) && <span className="published">Publicada</span>}</span></button><button className="template-delete" aria-label={`Eliminar ${template.name}`} title="Eliminar notificación" disabled={Boolean(busy)} onClick={() => void deleteNotification(template)}>×</button></div>)}{!visibleTemplates.length && <Empty title={project?.templates.length ? 'Sin coincidencias' : 'Cargá un export'} text={project?.templates.length ? 'Probá con otro filtro.' : 'Importá un JSON local o consultá ISC en modo de solo lectura.'} />}</div><footer className="sidebar-footer"><button className="clear-panel-button" aria-label="Limpiar panel de notificaciones" disabled={Boolean(busy) || !project?.templates.length} title={project?.templates.length ? 'Eliminar todas las notificaciones y adaptaciones locales' : 'No hay notificaciones para eliminar'} onClick={() => void clearNotifications()}><Icon name="trash" /></button></footer></aside>
      <section className="panel work-panel">{detail ? <><header className="work-header"><div><span className="eyebrow">{String(detail.original.key ?? 'Notificación ISC')}</span><h2>{String(detail.original.name ?? 'Sin nombre')}</h2><p className="subject-line"><span>Asunto {previewVersion === 'adapted' && detail.result ? 'adaptado' : 'original'}</span>{previewSubject}</p>{detail.provenance && <p className="provenance-line">Origen: {detail.provenance.connection_name} · {detail.provenance.template_type === 'standard' ? 'Estándar' : 'Personalizada'} · leída {new Date(detail.provenance.read_at).toLocaleString()}</p>}</div></header>{(detail.config_outdated || ((configDirty || guideDirty) && detail.result)) && <div className="outdated-banner"><Icon name="warn" /><div><strong>{configDirty || guideDirty ? 'Hay cambios de configuración o guía sin guardar' : 'La adaptación usa una configuración anterior'}</strong><p>{configDirty || guideDirty ? 'La adaptación actual no cambia hasta que guardes y vuelvas a generar.' : 'Podés revisarla; volvé a generar antes de publicar para aplicar la configuración vigente.'}</p></div></div>}
        {unsafeVelocity && <div className="unsafe-banner"><Icon name="warn" /><div><strong>Esta adaptación no es segura para descargar</strong><p>La IA cambió o eliminó {unsafeVelocityCount} referencia(s) Velocity. Revisá “Validación” y generá nuevamente o repará la copia en el editor.</p></div></div>}
        <div className="action-bar"><div className="action-context"><strong>{detail.result ? 'Original y adaptación disponibles' : 'Todavía no hay adaptación'}</strong><span>{generateDisabledReason || (detail.result ? 'Generar nuevamente reemplazará solo la copia adaptada.' : 'La generación siempre conserva el original.')}</span></div><div className="action-buttons"><button className="button primary" disabled={Boolean(generateDisabledReason)} title={generateDisabledReason} onClick={() => void adapt()}><Icon name="spark" />{busy === 'adapt' ? 'Generando…' : generationLabel}</button><button className="button secondary" disabled={Boolean(dateTranslationDisabledReason)} title={dateTranslationDisabledReason || 'Traduce días y meses después de la adaptación, sin usar IA.'} onClick={() => void toggleDateTranslation()}>{busy === 'date-translation' ? 'Procesando fechas…' : dateTranslationLabel}</button><button className="button secondary" disabled={Boolean(publicationDisabledReason)} title={publicationDisabledReason || 'Elegí el tenant destino y prepará el JSON con sus metadatos.'} onClick={() => setPublicationIntent('download')}><Icon name="download" />Descargar JSON para ISC</button><button className="button publish-button" disabled={Boolean(publicationDisabledReason)} title={publicationDisabledReason || 'Preparar, revisar y publicar esta adaptación o un lote.'} onClick={() => setPublicationIntent('publish')}>Publicar en ISC</button></div></div>
        <nav className="work-tabs" aria-label="Área de trabajo">{([['preview', 'Vista previa'], ['editor', 'Editar asunto y HTML'], ['diff', 'Diferencias'], ['validation', 'Validación']] as const).map(([tab, label]) => <button className={workTab === tab ? 'active' : ''} key={tab} onClick={() => setWorkTab(tab)}>{label}{tab === 'validation' && detail.validation?.suspicious && <span className="warn-dot" />}</button>)}</nav><div className="work-content">
          {workTab === 'preview' && <div className="preview-workspace"><div className="preview-controls"><div className="segmented" aria-label="Versión de vista previa"><button className={previewVersion === 'original' ? 'active' : ''} onClick={() => setPreviewVersion('original')}>Original</button><button className={previewVersion === 'adapted' ? 'active' : ''} disabled={!detail.result} title={!detail.result ? 'Generá una adaptación para habilitar esta versión.' : ''} onClick={() => setPreviewVersion('adapted')}>Adaptada</button></div></div>{!detail.result && <div className="inline-info"><Icon name="spark" /><span>Estás viendo el original. Abrí “Instrucciones y reglas” desde el engranaje y usá “{generationLabel}” para crear una copia adaptada.</span></div>}<div className="preview-version-label"><span className={previewVersion}>{previewVersion === 'adapted' ? 'Versión adaptada' : 'Versión original'}</span><strong>{previewSubject || 'Sin asunto'}</strong></div><iframe title={`Vista previa ${previewVersion === 'adapted' ? 'adaptada' : 'original'} aislada`} sandbox="" srcDoc={previewHtml} /><p className="preview-warning">Vista aislada: elimina scripts, no ejecuta Velocity y no garantiza el resultado final en Outlook o Gmail.</p></div>}
          {workTab === 'editor' && (detail.result ? <div className="editor-stack"><div className="editor-heading"><div><span className="eyebrow">Copia adaptada</span><h3>Editar asunto y HTML</h3></div><div className="editor-heading-actions"><div className="segmented" aria-label="Modo de edición"><button className={editorMode === 'visual' ? 'active' : ''} disabled={visualIssues.length > 0} title={visualIssues.length ? 'Este HTML contiene contenido que no puede editarse visualmente con seguridad.' : ''} onClick={() => setEditorMode('visual')}>Visual</button><button className={editorMode === 'html' ? 'active' : ''} onClick={() => setEditorMode('html')}>HTML</button></div><button className="button secondary" disabled={!!busy || (editorMode === 'visual' && (!visualIntegrity || visualIssues.length > 0))} title={!visualIntegrity ? 'Se alteró un elemento Velocity bloqueado. Recargá la plantilla antes de guardar.' : ''} onClick={() => void saveEdit()}><Icon name="save" />Guardar edición</button></div></div><label className="field"><span>Asunto adaptado</span><input value={subject} onChange={(event) => setSubject(event.target.value)} /><small>En modo visual, el backend rechazará el guardado si se altera una referencia Velocity del asunto.</small></label>{visualIssues.length > 0 && <div className="visual-unavailable"><Icon name="warn" /><div><strong>El modo visual está deshabilitado para este HTML</strong><p>{visualIssues.join('; ')}. Usá HTML para revisarlo o repararlo.</p></div><button className="button secondary" onClick={() => setEditorMode('html')}>Usar HTML</button></div>}{editorMode === 'visual' && visualIssues.length === 0 ? <SafeVisualEditor value={body} protectedBlocks={detail.protected_velocity_blocks ?? []} onChange={setBody} onIntegrityChange={setVisualIntegrity} /> : <label className="field grow"><span>HTML adaptado</span><textarea className="code-area" value={body} onChange={(event) => setBody(event.target.value)} /></label>}{detail.actions.length > 0 && <details className="metadata"><summary>Acciones del proveedor</summary><ul>{detail.actions.map((action) => <li key={action}>{action}</li>)}</ul></details>}</div> : <Empty title="Primero generá una adaptación" text="El original nunca se edita. La copia adaptada aparecerá acá." />)}
          {workTab === 'diff' && (detail.result ? <div className="diff-view"><div className="diff-legend"><span className="removed">− Original</span><span className="added">+ Adaptada</span></div><pre>{diff.map((line, index) => <div className={line.kind} key={index}><span>{line.kind === 'add' ? '+' : line.kind === 'remove' ? '−' : ' '}</span>{line.text || ' '}</div>)}</pre></div> : <Empty title="Sin diferencias todavía" text="Generá una adaptación para compararla con el original." />)}{workTab === 'validation' && <ValidationPanel validation={detail.validation} />}
        </div></> : <Empty title="Seleccioná o cargá una notificación" text="La vista previa y las acciones aparecerán en este espacio de trabajo." />}</section></main>{configOpen && config && project && <InstructionsRulesDialog config={config} provider={project.provider} dirty={configDirty} busy={busy} guide={styleGuide} guideContent={guideContent} guideFilename={guideFilename} guideDirty={guideDirty} onGuideContent={setGuideContent} onGuideFilename={setGuideFilename} onSaveGuide={() => void saveGuide()} onDeleteGuide={() => void deleteGuide()} onChange={setConfigField} onSave={() => void saveConfig()} onClose={() => setConfigOpen(false)} />}{aiOpen && project && <AISettings config={aiConfig} saved={savedAIConfig} provider={project.provider} apiKey={apiKey} busy={busy} onChange={setAIField} onApiKey={setApiKey} onSave={() => void saveAIConfig()} onTest={() => void testAIConnection()} onClose={closeAISettings} />}{iscConnectionsOpen && <ISCConnectionsDialog connections={iscConnections} onConnections={setISCConnections} onClose={() => setISCConnectionsOpen(false)} />}{iscImportOpen && project && <ISCImportDialog connections={iscConnections} templates={project.templates} onManageConnections={() => { setISCImportOpen(false); setISCConnectionsOpen(true) }} onImported={finishISCImport} onClose={() => setISCImportOpen(false)} />}{publicationIntent && project && <PublicationDialog connections={iscConnections} templates={project.templates} initialId={selectedId} intent={publicationIntent} onPublished={() => { void refreshAfterPublication() }} onClose={() => setPublicationIntent(null)} />}</div>
}

export default App
